def pad(data):
    """Pad the input data to be a multiple of AES block size (16 bytes)."""
    return data + (AES.block_size - len(data) % AES.block_size) * chr(AES.block_size - len(data) % AES.block_size)

def unpad(data):
    """Unpad the input data."""
    return data[:-ord(data[-1:])]

def encrypt_data(plain_text):
    """Encrypt data using AES."""
    private_key = PBKDF2(SECRET_KEY, SALT, dkLen=32, count=100000)
    cipher = AES.new(private_key, AES.MODE_CBC)
    cipher_text = cipher.encrypt(pad(plain_text).encode('utf-8'))
    return base64.b64encode(cipher.iv + cipher_text).decode('utf-8')

def decrypt_data(encrypted_text):
    """Decrypt data using AES."""
    private_key = PBKDF2(SECRET_KEY, SALT, dkLen=32, count=100000)
    encrypted_data = base64.b64decode(encrypted_text)
    iv = encrypted_data[:AES.block_size]
    cipher_text = encrypted_data[AES.block_size:]
    cipher = AES.new(private_key, AES.MODE_CBC, iv)
    plain_text = unpad(cipher.decrypt(cipher_text).decode('utf-8'))
    return plain_text

