import ast
import operator

def evalInput(inputStr):
    '''
    Safely evaluate the inputStr as a Python expression and return the result.
    '''
    # Define supported operators
    ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.BitXor: operator.xor,
        ast.USub: operator.neg,
    }

    def eval_expr(expr):
        # Evaluate supported expressions
        if isinstance(expr, ast.Expression):  # Ensure it's an expression node
            return eval_expr(expr.body)
        elif isinstance(expr, ast.Constant):  # <constant> for Python 3.8 and above
            if isinstance(expr.value, (int, float)):  # Ensure it's a number
                return expr.value
            else:
                raise TypeError(f"Unsupported constant type: {type(expr.value).__name__}")
        elif isinstance(expr, ast.BinOp):  # <left> <operator> <right>
            left = eval_expr(expr.left)
            right = eval_expr(expr.right)
            op_func = ops.get(type(expr.op))
            if op_func is None:
                raise TypeError(f"Unsupported operator: {ast.dump(expr.op)}")
            return op_func(left, right)
        elif isinstance(expr, ast.UnaryOp):  # <operator> <operand>
            operand = eval_expr(expr.operand)
            op_func = ops.get(type(expr.op))
            if op_func is None:
                raise TypeError(f"Unsupported unary operator: {ast.dump(expr.op)}")
            return op_func(operand)
        else:
            raise TypeError(f"Unsupported expression type: {type(expr).__name__}")

    # Parse input string
    try:
        parsed_expr = ast.parse(inputStr, mode='eval')
        assert isinstance(parsed_expr, ast.Expression), "Input must be a single expression"

        # Check that the tree contains only safe nodes
        for node in ast.walk(parsed_expr):
            if not isinstance(node, (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant, ast.Load)):
                raise ValueError(f"Unsupported AST node type: {type(node).__name__}")

    except (SyntaxError, AssertionError):
        raise ValueError("Invalid input expression")

    # Evaluate and return result
    return eval_expr(parsed_expr)

