        # Use dnslib to create a DNS Record from raw data
        dns_record = dnslib.DNSRecord.parse(data)
        return dns_record
    except dnslib.DNSError as e:
        raise ValueError(f"Invalid DNS packet: {e}")

def resolveName(nameToResolve):
    # Use DNS-over-HTTPS (DoH) for secure DNS resolution
    doh_url = "https://dns.google/resolve"  # Example of a secure DoH server
    params = {
        'name': nameToResolve,
        'type': 'A',  # DNS record type, 'A' for IPv4 addresses
    }
    try:
        response = requests.get(doh_url, params=params)
        response.raise_for_status()  # Raise an error for bad HTTP status
        json_response = response.json()
        if 'Answer' in json_response:
            return json_response['Answer']
        else:
            raise ValueError(f"No DNS Answer found for {nameToResolve}")
    except requests.RequestException as e:
        raise ValueError(f"DoH request failed: {e}")

def sendResponse(requestIP, record, udp_port):
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as response_socket:
        try:
            # For simplicity, send the first answer only
            answer = record[0]['data']
            response_socket.sendto(answer.encode(), (requestIP, udp_port))
        except Exception as e:
            print(f"Failed to send response: {e}")

def UDPMessaging(udp_ip, udp_port):
    # Create a UDP socket
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as server_socket:
        server_socket.bind((udp_ip, udp_port))

        while True:
            try:
                # Listen for incoming data
                data, addr = server_socket.recvfrom(1024)  # buffer size is 1024 bytes

                # Parse the received data
                parsed_packet = parseUDPpacket(data)

                # Extract the question section for resolution
