def upload_pdf():
    """
    Get PDF file from request, save it to ./uploads directory, and redirect to /pdf/view.
    """
    if 'file' not in request.files:
        return abort(400, 'No file part in the request')

    file = request.files['file']
    if file.filename == '':
        return abort(400, 'No file selected')

    # Ensure the uploaded file is a PDF
    if not file.filename.lower().endswith('.pdf'):
        return abort(400, 'Selected file is not a PDF')

    # Sanitize the filename and save the file securely
    filename = werkzeug.utils.secure_filename(file.filename)
    file_path = os.path.normpath(os.path.join(UPLOAD_DIRECTORY, filename))

    # Verify the final resolved path is within the upload directory
    if not os.path.realpath(file_path).startswith(os.path.realpath(UPLOAD_DIRECTORY)):
        return abort(400, 'Invalid file path')

    file.save(file_path)

    return redirect('/pdf/view', 302)

if __name__ == "__main__":
    app.run()

